  let wc = 1.0 / (1.0 + max(c.r, max(c.g, c.b)));
  let wd = 1.0 / (1.0 + max(d.r, max(d.g, d.b)));
  let avg = (a * wa + b * wb + c * wc + d * wd) / (wa + wb + wc + wd) + sc;
